BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_vid'
def K(w):return 'https://en.wiktionary.org/wiki/'+w
def S(w):return 'https://www.etymonline.com/word/'+w
def M(w):return 'https://www.merriam-webster.com/dictionary/'+w
def O(w):return 'https://www.oxfordlearnersdictionaries.com/definition/english/'+w
def A(h,w,m):return h+[[w,m]]
B=[['拉丁 vir','成年男子；男人']]
POWER=B+[['拉丁 virtus，词干 virtut-','勇气、力量、卓越；品德、效能']]
VIRTUE=POWER+[['古法语／盎格鲁法语 vertu → 中古英语 vertu → virtue','美德、优点；也保留力量、效能一面']]
VIRTUAL=POWER+[['中世纪拉丁 virtualis → 古法语 vertual／直接拉丁借入','有力量、有产生效果的能力'],['中古英语 virtual → 英语 virtual','效果上相当于、实质上的 → 计算机中的虚拟']]
VIRTUALIZE=A(VIRTUAL,'英语 virtual + -ize → virtualize','使虚拟化；以软件方式提供相应功能')
VIRTUOSO=POWER+[['晚期拉丁 virtuosus → 意大利 virtuoso','优秀、富有才识的；有才识的人'],['英语借入 virtuoso','早期艺术鉴赏者 → 技艺特别高超的表演者或专家']]
TECH='https://www.redhat.com/en/topics/virtualization/what-is-virtualization'
W=[
E('virtue','英 /ˈvɜːtʃuː/；美 /ˈvɜːrtʃuː/','美德；优点、长处；凭借〔by virtue of〕','一个人做得值得尊重的地方，或一个东西确实好用的地方；诚实可以是 virtue，方案简单也可以是 a virtue。','拉丁 vir“男人”形成 virtus，历史上包含勇气、力量、卓越和品德，经法语 vertu 进入英语。现代美德与优点不限于任何性别；by virtue of 保留“凭其效力”的旧支线。',VIRTUE,'a virtue 可是一种美德或优点；the virtues of a method 是某方法的长处。by virtue of experience 是凭借经验、由于经验起作用，不是“凭经验的道德”。','the virtue of patience；the virtues of；by virtue of；make a virtue of necessity。','virtue 常可译美德，但谈设计、办法时更自然译优点。advantage 偏有利条件，virtue 更像事物自身值得肯定的特点。',('Patience is a virtue that this job demands every day.','这份工作每天都需要耐心这种美德。'),('The main virtue of the design is its simplicity.','这个设计的主要优点是简单。'),('She knew the area well by virtue of having worked there for years.','她在那里工作多年，因此很熟悉那一带。'),sources=[S('virtue'),K('virtue'),O('virtue')]),
E('virtuous','英 /ˈvɜːtʃuəs/；美 /ˈvɜːrtʃuəs/','有美德的；品行正直的；良性的','人的做法符合自己或社会认可的道德标准；谈一连串结果时，好的变化还会继续推动更多好变化。','经古法语 vertuos、盎格鲁法语 vertuous 来自晚期拉丁 virtuosus，远接 virtus。现代可对应 virtue + -ous，但实际拉丁、法语形容词早已存在。',POWER+[['晚期拉丁 virtuosus → 古法语 vertuos／盎格鲁法语 vertuous','有力量、有好品质的'],['中古英语 vertuous → 英语 virtuous','有美德；正直的；用于良性循环']],'a virtuous person 说品行；feel virtuous 有时带一点自我打趣，觉得自己做了件好事；a virtuous circle 是互相促进的良性循环。旧文中还可能带贞洁的意思。','virtuous behaviour；feel virtuous；a virtuous circle；a virtuous cycle。','virtuous 说道德或良性效果；virtuoso 说技艺高超。一个表演者技术出众，并不能只凭此判断其品行。',('The novel makes its most virtuous character surprisingly funny.','这部小说把品行最正直的角色写得出人意料地幽默。'),('Better service brought more customers, creating a virtuous circle.','更好的服务带来更多顾客，形成了良性循环。'),sources=[S('virtuous'),K('virtuous'),O('virtuous')]),
E('virtual','英 /ˈvɜːtʃuəl/；美 /ˈvɜːrtʃuəl/','实质上的、几乎等同的；虚拟的；线上进行的','外在形式未必完全是那回事，作用或体验却已经很接近：不是正式承认，却相当于承认；没有一间真实教室，也能在线上课。','来自中世纪拉丁 virtualis，接 virtus 的力量、效能义。路线是“能产生效果”到“效果上相当于”，再发展计算机用法；不能从现代 virtue“美德”硬译成“有道德的”。',VIRTUAL,'a virtual certainty 是几乎确定的事；a virtual tour 是借数字媒介游览；a virtual machine 是软件提供的机器环境。virtual meeting 常说线上会议，其中的人与讨论是真实的。','a virtual certainty；a virtual monopoly；virtual reality；a virtual meeting；a virtual machine。','virtual 不总是“虚假的”：非技术语境可能说实质上、近乎；技术语境强调呈现或实现方式。fake 则常暗含伪造、冒充。',('His silence was a virtual admission that the plan had failed.','他的沉默几乎等于承认计划已经失败。'),('We took a virtual tour of the museum before visiting in person.','亲自参观前，我们先在线上游览了博物馆。'),('The training session will take place in a virtual classroom.','培训将在虚拟教室中进行。'),sources=[S('virtual'),K('virtual'),O('virtual'),TECH]),
E('virtually','英 /ˈvɜːtʃuəli/；美 /ˈvɜːrtʃuəli/','几乎；实际上；以虚拟或线上方式','差得太少，以至于实际可以当成那样；在另一类句子里，则表示借助数字方式参与或体验。','virtual + -ly，英语副词；较早的“在效果上”义发展出几乎、实际上，数字媒介义是后来继承 virtual 的新用法。',A(VIRTUAL,'英语 virtual + -ly → virtually','效果上、几乎；后来也用于数字或线上方式'),'virtually impossible 是几乎不可能；virtually everyone 是几乎每个人；attend virtually 在会议语境中常是线上参加。必须看它修饰什么，不能总翻成“虚拟地”。','virtually impossible；virtually all；virtually identical；meet virtually；attend virtually。','almost 常可替换几乎这一义；actually 并不总能替换，因为 virtually 可能保留一点差距。参加方式的 virtually 也不是“差点参加”。',('The two versions are virtually identical.','这两个版本几乎完全相同。'),('Several colleagues joined the workshop virtually.','几位同事在线上参加了工作坊。'),sources=[S('virtually'),K('virtually'),O('virtually')]),
E('virtualize','英 /ˈvɜːtʃʊəlaɪz/；美 /ˈvɜːrtʃəwəlaɪz/','使虚拟化','把原来紧贴某一块实体硬件的功能，用软件组织成可分配的环境，让使用者像使用独立资源那样使用它。','英语 virtual + -ize，表示使成为 virtual；英式也拼 virtualise。这里承接的是计算机义，不是“使人有美德”。',VIRTUALIZE,'virtualize servers 常指把服务器工作负载放进虚拟环境；virtualize a desktop 是提供虚拟桌面环境。底下仍需真实硬件，改变的是资源呈现与分配方式。','virtualize servers；virtualize a desktop；virtualize computing resources。','simulate 可以泛指模拟某种行为或情景；virtualize 在计算机语境中通常指提供可实际运行或使用的虚拟资源，范围更具体。',('The team plans to virtualize several older servers.','团队计划把几台较旧服务器的环境虚拟化。'),('The software can virtualize a desktop for each user.','这套软件能为每位用户提供虚拟桌面环境。'),sources=[K('virtualize'),'https://www.collinsdictionary.com/dictionary/english/virtualize',M('virtualization'),TECH]),
E('virtualized','英 /ˈvɜːtʃʊəlaɪzd/；美 /ˈvɜːrtʃəwəlaɪzd/','已虚拟化的；使虚拟化了','环境已经被放到虚拟化这一层来提供：看起来是各自独立的系统，实际资源可来自共享硬件。','virtualize + -ed，末尾已有 e，只加 d；词尾读 /d/。可作过去分词形容环境，也可作为过去式说明做过虚拟化。',A(VIRTUALIZE,'英语 virtualize → virtualized','已通过虚拟化方式实现的；完成了虚拟化'),'a virtualized environment 是经过虚拟化组织的环境；virtualized servers 常与 physical servers 对照。它描述技术实现，不意味着数据或业务是假的。','a virtualized environment；virtualized servers；virtualized infrastructure。','virtual 是较宽的形容词；virtualized 特别指出已经经过虚拟化处理或部署。virtual reality 的所有体验不能都改称 virtualized reality。',('The application runs in a virtualized environment during testing.','测试期间，这个应用在虚拟化环境中运行。'),('The report compares the physical and virtualized server setups.','报告比较了实体服务器与虚拟化服务器的部署方式。'),sources=[K('virtualized'),M('virtualization'),'https://www.collinsdictionary.com/dictionary/english/virtualize',TECH]),
E('virtualization','英 /ˌvɜːtʃʊəlaɪˈzeɪʃən/；美 /ˌvɜːrtʃəwələˈzeɪʃən/','虚拟化','把硬件资源与使用它们的环境隔开来管理：一台实体机器的资源可以分给多个虚拟环境，各自承担工作。','virtual + -ization，也可按 virtualize + -ation 理解，是英语技术名词；不把现代计算机概念直接当成拉丁原义。',A(VIRTUAL,'英语 virtual + -ization → virtualization','建立和管理虚拟资源、虚拟环境的过程或技术'),'server virtualization 是服务器虚拟化；desktop virtualization 是桌面虚拟化。理解词义先抓“通过一层软件提供资源”，不必把它与某一个厂商或某一种产品绑定。','server virtualization；desktop virtualization；a virtualization platform；virtualization software。','virtualization 是技术过程；virtual reality 是虚拟现实体验，两者不是同一个概念。cloud computing 与虚拟化常有关联，但不能互作定义。',('Virtualization allows the lab to run several test environments on one machine.','虚拟化让实验室能在一台机器上运行几个测试环境。'),('The course introduces virtualization before discussing cloud services.','这门课先介绍虚拟化，再讨论云服务。'),sources=[K('virtualization'),M('virtualization'),'https://www.collinsdictionary.com/dictionary/english/virtualize',TECH]),
E('virtuoso','英 /ˌvɜːtʃuˈəʊsəʊ/；美 /ˌvɜːrtʃuˈoʊsoʊ/','技艺大师；演奏高手；技艺精湛的','别人觉得极难的动作，他或她做得熟练、准确，甚至像轻而易举；常见于音乐，也能扩展到其他高水平技艺。','从意大利 virtuoso 借入，接晚期拉丁 virtuosus，远接 virtus“卓越、能力”。早期英语还指有艺术学识或鉴赏力的人，后来更集中于高超表演技能。',VIRTUOSO,'a violin virtuoso 是小提琴高手；a virtuoso performance 可以把 virtuoso 放在名词前。复数 virtuosos 和意大利式 virtuosi 都可见。这里表扬的是技艺，不是道德。','a piano virtuoso；a violin virtuoso；a virtuoso performance；a virtuoso display。','expert 泛指专家；virtuoso 常让人想到高难度技能的精彩展现。virtuous 则说品行，拼写接近，现代判断维度不同。',('The young violin virtuoso made the difficult passage sound effortless.','这位年轻小提琴高手把高难度乐段拉得轻松自如。'),('The chef gave a virtuoso display of knife skills.','厨师精彩展示了炉火纯青的刀工。'),sources=[S('virtuoso'),K('virtuoso'),O('virtuoso')]),
E('virtuosity','英 /ˌvɜːtʃuˈɒsəti/；美 /ˌvɜːrtʃuˈɑːsəti/','精湛技艺；高超技巧','不指那个高手本人，而指让人看出其厉害的技能：手指、声音、语言或动作能做到别人难以做到的程度。','现代艺术义按 virtuoso + -ity 形成，去掉末尾 o。更早英语另有从中世纪拉丁 virtuositas 借入的旧义；现代“精湛技艺”不能直接解释成“道德很好”。',A(VIRTUOSO,'近代英语 virtuoso + -ity → virtuosity','艺术鉴赏兴趣 → 高度娴熟的技艺'),'technical virtuosity 强调技术娴熟；a display of virtuosity 是一次高手级展示。评论有时说只有 virtuosity 而缺感情，此时并非否认技巧，而是认为技巧尚未变成打动人的表达。','technical virtuosity；pianistic virtuosity；a display of virtuosity；astonishing virtuosity。','virtuoso 是人或定语，virtuosity 是技能。skill 更普通；virtuosity 常意味着高水平、甚至令人惊叹的熟练。',('The performance combined technical virtuosity with a remarkably gentle tone.','这场演奏把精湛技巧与格外柔和的音色结合起来。'),('The reviewer admired the writer’s verbal virtuosity but wanted stronger characters.','评论者欣赏作者驾驭语言的高超技巧，但希望人物更有力量。'),sources=[S('virtuosity'),K('virtuosity'),M('virtuosity'),O('virtuosity')]),
E('virtuosic','英 /ˌvɜːtʃuˈɒsɪk/；美 /ˌvɜːrtʃuˈɑːsɪk/','技艺精湛的；高手式的；炫技的〔依语境〕','形容一次表演或一种写法，把难度高的东西控制得十分熟练，技巧本身很醒目。','virtuoso 去末尾 o + -ic，英语形容词。它与 virtuous“有美德”虽然远源相同，不能按相似拼写混用。',A(VIRTUOSO,'英语 virtuoso + -ic → virtuosic','具有高手技艺特征的'),'virtuosic playing 常是赞赏精湛演奏；virtuosic prose 可说文字技巧娴熟。若上下文批评只有花样，则可译炫技，但这个词本身并不必然贬义。','virtuosic playing；a virtuosic passage；virtuosic prose；a virtuosic display。','virtuoso 可直接修饰 performance，virtuosic 也是相关形容词；virtuosity 则是名词。virtuous music 不是“技巧高超的音乐”的常规表达。',('The concerto ends with a virtuosic passage for the soloist.','这首协奏曲以一段考验独奏者高超技巧的乐段收尾。'),('Her virtuosic prose turns a simple walk into a vivid adventure.','她娴熟的文字把一次普通散步写成了鲜活的冒险。'),sources=[K('virtuosic'),M('virtuosic'),S('virtuoso')]),
E('virile','英 /ˈvɪraɪl/；美 /ˈvɪrəl/','有阳刚气的；精力旺盛的〔尤其可含男性性活力〕','文字或形象把强健、活力、性吸引等传统上与成年男性联系的特征放大出来；它不只是中性说明一个人是男性。','法语 viril 或拉丁 virilis 借入英语，vir“男人”+ 拉丁形容词后缀 -ilis。它保留了这条男性特征支线，不走 virtual 的效能支线。',B+[['拉丁 virilis → 法语 viril／直接拉丁借入','与成年男子有关的'],['英语 virile','被视为阳刚、强健或富于男性性活力的']],'a virile image 是阳刚形象；文艺评论可能用 virile 形容有力的表现。它带着文化上的性别联想，不能把字面评价当作身体状况的测量。','a virile image；a virile performance；a virile hero。','male 主要说明男性；virile 还加上强健、性活力等联想。vigorous 更一般地说有力、精力充沛，不限定这层男性形象。',('The poster presents the hero as a rugged, virile figure.','海报把主人公塑造成粗犷、阳刚的人物。'),('The essay examines the actor’s carefully constructed virile image.','文章分析了这位演员精心塑造的阳刚形象。'),sources=[S('virile'),K('virile'),O('virile')]),
E('virility','/vəˈrɪləti/','阳刚气；男性活力，尤指性活力','把 virile 描述的那组特征作为一种品质来谈：是塑造出来的形象、本人关心的活力，还是某个文化符号，要看上下文。','借法语 virilité，来自拉丁 virilitas，接 virilis“男性的”。现代可与 virile + -ity 对照，但名词有自己的拉丁、法语借入路线。',B+[['拉丁 virilis → virilitas → 法语 virilité','男性相关特征 → 成年男子状态、男性活力'],['英语 virility','阳刚特征；男性性活力等']],'a symbol of virility 是象征男性活力的符号；讨论艺术或广告时，常是在分析一种形象。这个词的文化含义很宽，不能凭它推断具体生育能力。','a symbol of virility；an image of virility；ideas of virility。','fertility 特指生育能力这一领域；virility 还常含力量、男性气质和性活力的联想，两词不能直接画等号。',('The statue was interpreted as a symbol of virility and strength.','这尊雕像被解读为男性活力与力量的象征。'),('The novel explores its hero’s anxiety about ageing and virility.','小说探讨了主人公对衰老与男性活力的焦虑。'),sources=[S('virility'),K('virility'),O('virility')]),
E('triumvirate','/traɪˈʌmvərət/','三人执政集团；三人领导小组；三巨头组合','重要决定由三个人共同掌握；后来也可以把某领域特别有影响的三个人或三方称作一个 triumvirate。','借拉丁 triumviratus，接 triumvir；更早与 trium virum“属于三个人的”有关，trium 是三的属格形式，virum 是 vir 的旧式复数属格。不是 triumph“胜利”加词尾。',B+[['拉丁 tres viri，属格短语 trium virum → triumvir','三个人 → 三人共职中的一员'],['拉丁 triumviratus → 英语 triumvirate','三人共职、执政；后来泛指有权力或影响力的三人组合']],'古罗马史中可指三头政治；新闻和评论中 a triumvirate of leaders 也可泛指三人领导组合。现代引申不必限定全为男性，核心是三方共同占据重要位置。','a ruling triumvirate；a triumvirate of leaders；form a triumvirate。','trio 只说三个组成的一组；triumvirate 通常额外带领导、权力或显著影响的意味，语气也更正式。',('A triumvirate of directors led the organisation through its early years.','该组织早期由三位董事组成的领导小组带领。'),('The chapter compares the ambitions of the three members of the triumvirate.','这一章比较了三人执政集团中各成员的抱负。'),sources=[S('triumvirate'),K('triumvirate'),O('triumvirate')]),
]
